parameters.jsCode:
const incoming = $json.body ?? $json;

if (!incoming.files || !Array.isArray(incoming.files) || incoming.files.length === 0) {
  throw new Error('Payload files kosong. Data yang diterima: ' + JSON.stringify($json));
}

function extractDriveFileId(file) {
  const direct = String(file.drive_file_id || file.id || file.file_id || '').trim();
  if (direct) return direct;

  const url = String(file.drive_url || file.url || file.webViewLink || '').trim();
  if (!url) return '';

  let m = url.match(/\/d\/([a-zA-Z0-9_-]{20,})/);
  if (m) return m[1];
  m = url.match(/[?&]id=([a-zA-Z0-9_-]{20,})/);
  if (m) return m[1];
  return '';
}

return incoming.files.map((file, idx) => {
  const driveFileId = extractDriveFileId(file);
  if (!driveFileId) {
    throw new Error(`File ID kosong pada image_index ${idx + 1}. Payload file: ${JSON.stringify(file)}`);
  }

  return {
    json: {
      submitted_at: incoming.submitted_at || '',
      tanggal_submit: incoming.tanggal_submit || '',
      jam_submit: incoming.jam_submit || '',
      jam_laporan: incoming.jam_laporan || '',
      response_id: incoming.response_id || '',
      batch_id: incoming.batch_id || ('BATCH-' + Date.now()),
      respondent_email: incoming.respondent_email || '',
      form_title: incoming.form_title || '',
      tx: file.tx || incoming.tx || '',
      image_index: file.image_index || (idx + 1),
      image_name: file.image_name || ('image_' + (idx + 1)),
      drive_file_id: driveFileId,
      drive_url: file.drive_url || '',
      mime_type: file.mime_type || ''
    }
  };
});

// Jeda aman anti rate-limit 3 detik (murni in-memory event loop, anti-freeze scheduler n8n)
await new Promise(resolve => setTimeout(resolve, 4000));

const source = $('Loop Over Images (Batch 1)').item.json;
let base64Image = '';

try {
  const binaryObj = $input.item.binary || $binary || {};
  const binKey = Object.keys(binaryObj)[0] || 'data';

  if (this.helpers && typeof this.helpers.getBinaryDataBuffer === 'function') {
    const buffer = await this.helpers.getBinaryDataBuffer(0, binKey);
    if (buffer && buffer.length > 0) {
      base64Image = buffer.toString('base64');
    }
  }

  if (!base64Image && binaryObj[binKey]?.data) {
    base64Image = binaryObj[binKey].data;
  }
} catch (err) {
  const binaryObj = $input.item.binary || $binary || {};
  const binKey = Object.keys(binaryObj)[0] || 'data';
  if (binaryObj[binKey]?.data) {
    base64Image = binaryObj[binKey].data;
  }
}

if (!base64Image) {
  throw new Error('Data biner gambar tidak ditemukan untuk file: ' + (source.image_name || source.drive_file_id));
}

const prompt = `Analisis foto layar panel status Power Amplifier (PA) transmitter pemancar ST Joglo ini.\nEkstrak seluruh parameter metrik teknis ke dalam format JSON murni.\n\nFormat JSON yang wajib dihasilkan (hanya key berikut):\n{\n  "monitor_status": "MON / RUN / STS / ALM / OFF",\n  "db_value": "nilai dB desimal (misal 49.57)",\n  "pa_id": "identitas PA (misal PA-01, PA-02, sampai PA-10)",\n  "op_w": "daya output Watt (angka bulat, range normal 500-1200, misal 1016)",\n  "rp_w": "daya reflected Watt (angka. Jika 0 atau mendekati 0, tulis 0)",\n  "temp_c": "temperatur Celsius (angka bulat/desimal, misal 38)",\n  "dg_v": "tegangan DC Volt (angka desimal, misal 40.2)",\n  "dpa1_a": "arus Driver PA 1 Ampere (angka desimal, misal 0.6)",\n  "dpa2_a": "arus Driver PA 2 Ampere (angka desimal, misal 4.2)",\n  "fpa1_a": "arus Final PA 1 Ampere (angka desimal, misal 8.5)",\n  "fpa2_a": "arus Final PA 2 Ampere (angka desimal, misal 8.6)",\n  "fpa3_a": "arus Final PA 3 Ampere (angka desimal, misal 8.5)",\n  "fpa4_a": "arus Final PA 4 Ampere (angka desimal, misal 8.7)",\n  "fpa5_a": "arus Final PA 5 Ampere (angka desimal, misal 8.4)",\n  "fpa6_a": "arus Final PA 6 Ampere (angka desimal, misal 8.5)",\n  "fpa7_a": "arus Final PA 7 Ampere (angka desimal, misal 8.6)",\n  "fpa8_a": "arus Final PA 8 Ampere (angka desimal, misal 8.5)"\n}\n\nAturan Penting:\n1. Kembalikan HANYA angka untuk nilai numerik, tanpa menyertakan unit (W, V, A, C, dB). Contoh: "1016", bukan "1016 W".\n2. Khusus rp_w jika bernilai nol, tulis "0".\n3. Jika ada angka/field yang tidak terbaca, tertutup, atau rusak, isi dengan string "tidak terbaca".\n4. Kembalikan HANYA JSON murni tanpa markdown, kutipan backtick, atau teks tambahan apapun.`;

return {
  json: {
    source_meta: source,
    gemini_body: {
      contents: [
        {
          role: "user",
          parts: [
            { text: prompt },
            {
              inline_data: {
                mime_type: "image/jpeg",
                data: base64Image
              }
            }
          ]
        }
      ],
      generationConfig: {
        responseMimeType: "application/json",
        temperature: 0.1
      }
    }
  }
};

const prep = $('Code - Prepare Gemini Payload').item.json;
const source = prep.source_meta || {};
const apiResponse = $json || {};

function cleanNumber(val) {
  if (val === null || val === undefined || val === '') return 'tidak terbaca';
  let s = String(val).trim().replace(/,/g, '.').replace(/[^0-9.-]/g, '');
  return s !== '' ? s : 'tidak terbaca';
}

let parsedData = {};
let rawText = '';
let parseStatus = 'ok';

try {
  const textCandidate = apiResponse.candidates?.[0]?.content?.parts?.[0]?.text;
  if (textCandidate) {
    rawText = textCandidate;
    let cleanJsonStr = textCandidate.replace(/```json/gi, '').replace(/```/g, '').trim();
    parsedData = JSON.parse(cleanJsonStr);
  } else if (apiResponse.error) {
    parseStatus = 'error: ' + (apiResponse.error.message || JSON.stringify(apiResponse.error));
    rawText = JSON.stringify(apiResponse);
  } else {
    parseStatus = 'empty_response';
    rawText = JSON.stringify(apiResponse);
  }
} catch (err) {
  parseStatus = 'json_parse_error: ' + err.message;
  rawText = JSON.stringify(apiResponse);
}

let paId = String(parsedData.pa_id || '').trim().toUpperCase();
if (!paId || paId === 'TIDAK TERBACA') {
  paId = source.image_index ? 'PA-' + String(source.image_index).padStart(2, '0') : 'PA-01';
}

const unique_id = `${source.response_id || ''}_${source.tx || ''}_${paId}_${source.drive_file_id || ''}`;

const record = {
  submitted_at: source.submitted_at || '',
  response_id: source.response_id || '',
  batch_id: source.batch_id || '',
  respondent_email: source.respondent_email || '',
  form_title: source.form_title || '',
  image_index: source.image_index || '',
  image_name: source.image_name || '',
  drive_file_id: source.drive_file_id || '',
  drive_url: source.drive_url || '',
  unique_id: unique_id,
  monitor_status: String(parsedData.monitor_status || 'MON').trim().toUpperCase(),
  db_value: cleanNumber(parsedData.db_value),
  pa_id: paId,
  op_w: cleanNumber(parsedData.op_w),
  rp_w: parsedData.rp_w !== undefined && parsedData.rp_w !== null ? cleanNumber(parsedData.rp_w) : '0',
  temp_c: cleanNumber(parsedData.temp_c),
  dg_v: cleanNumber(parsedData.dg_v),
  dpa1_a: cleanNumber(parsedData.dpa1_a),
  dpa2_a: cleanNumber(parsedData.dpa2_a),
  fpa1_a: cleanNumber(parsedData.fpa1_a),
  fpa2_a: cleanNumber(parsedData.fpa2_a),
  fpa3_a: cleanNumber(parsedData.fpa3_a),
  fpa4_a: cleanNumber(parsedData.fpa4_a),
  fpa5_a: cleanNumber(parsedData.fpa5_a),
  fpa6_a: cleanNumber(parsedData.fpa6_a),
  fpa7_a: cleanNumber(parsedData.fpa7_a),
  fpa8_a: cleanNumber(parsedData.fpa8_a),
  raw_text: rawText,
  parse_status: parseStatus,
  tx: source.tx || '',
  jam_laporan: source.jam_laporan || '',
  jam_submit: source.jam_submit || ''
};

return { json: record };
